if mode=='tests':
 profile=p/'offline-proof.sb';name='affected-render-and-packing'
 command=[py,'-m','pytest','tests/test_china_archetype_d_s1.py','tests/test_risk_radar_dlg_country_wiring.py','tests/test_ci_pack.py::test_exclusive_curation_narrows_ordinary_code_prs','tests/test_ci_pack.py::test_curated_exclusive_scopes_cover_their_own_import_closure','-q','--basetemp',str(p/'pytest-current-tmp'),'--junitxml',str(p/(name+'.xml')),'-o','log_file='+str(p/(name+'-pytest.log')),'-o','cache_dir='+str(p/'pytest-cache')]
 steps=[(name,command)]
else:
 profile=p/'loopback-capture.sb';steps=[('actual-capture',[py,str(p/'capture-current.py')]),('synthetic-cases',[py,str(p/'synthetic-current.py')])]
report={'operation':src['operation'],'base':src['M'],'mode':mode,'profile_sha256':ident(profile)['sha256'],'source_and_inputs_before':expected,'started_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'python':sys.version,'steps':[]}
for name,command in steps:
 argv=['/usr/bin/sandbox-exec','-f',str(profile),*command];log=p/(name+'.log');assert not log.exists();start=time.monotonic()
 with log.open('w') as out:
  proc=subprocess.Popen(argv,cwd=w,env=env,stdout=out,stderr=subprocess.STDOUT)
  report['active']={'step':name,'pid':proc.pid,'argv':argv};target.write_text(json.dumps(report,indent=2)+'\n')
  print(json.dumps({'step':name,'pid':proc.pid,'started_at':datetime.datetime.now(datetime.timezone.utc).isoformat()}),flush=True);rc=proc.wait()
 entry={'step':name,'pid':proc.pid,'argv':argv,'returncode':rc,'seconds':round(time.monotonic()-start,3),'log':ident(log)}
 junit=p/(name+'.xml')
 if junit.exists():
  root=ET.parse(junit).getroot();suites=[root] if root.tag=='testsuite' else list(root.iter('testsuite'))
  entry['junit']={k:sum(int(s.get(k,0)) for s in suites) for k in ('tests','failures','errors','skipped')}
 report['steps'].append(entry);report.pop('active',None);target.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps(entry),flush=True)
 for line in log.read_text(errors='replace').splitlines()[-13:]:print(line[:700],flush=True)
 if rc:print('PROOF_STOPPED_ON_FAILURE',flush=True);sys.exit(rc)
